  readonly truncatedCalls: TruncatedCall[];

  constructor(
    kind: InferenceFailureKind,
    origin: InferenceFailureOrigin,
    message: string,
    opts: {
      httpStatus?: number;
      requestId?: string;
      partialText?: string;
      failoverEligible?: boolean;
      transportCause?: TransportCause[];
      condition?: ProviderCondition;
      execution?: ExecutionStatus;
      hints?: ProviderHints;
