export class RecoveryCancelled extends Error {
  constructor() {
    super("Cancelled while waiting for the inference provider");
    this.name = "RecoveryCancelled";
  }
}

export interface ProbeResult {
  available: boolean;
  condition: ProviderCondition;
  httpStatus?: number;
  hints?: ProviderHints;
  detail?: string;
  /** The probe's own deadline fired (the connection may be fine, just slow). */
  timedOut?: boolean;
  /** Error codes from the transport's cause chain (ECONNREFUSED, ENOTFOUND, ...): structured, never read from text. */
  codes?: string[];
}

/**
