        for (;;) {
          const delay = nextDelayMs(consecutive, hints, this.policy, this.clock.random);
          const elapsed = this.clock.now() - firstFailureAt;
          if (execution === "NOT_EXECUTED" && hooks.shouldYield?.(failure, delay)) {
