    if (this.record) return;
    const now = this.iso();
    this.record = {
      state: "WAITING",
      step: this.step,
      startedAt: now,
      updatedAt: now,
      condition,
      submissions: [],
      probes: 0,
      waitedMs: 0,
      unknownReplays: 0,
      ...(this.options.endpoint ? { endpoint: persistableEndpoint(this.options.endpoint) } : {}),
      ...(this.options.everSucceeded !== undefined ? { everSucceeded: this.options.everSucceeded } : {}),
