  }

  private transition(state: ProviderRecoveryRecord["state"], extra: Partial<ProviderRecoveryRecord>, hooks: RecoveryHooks<unknown>): void {
    const r = this.record!;
    r.state = state;
    r.updatedAt = this.iso();
